const r = await Promise.allSettled([
  tools.exec_command({cmd:"pwd && rg --files -g 'AGENTS.md' -g 'configdata.yml' -g '*help*' qutebrowser doc tests | head -80",workdir:"/app",max_output_tokens:3000}),
  tools.exec_command({cmd:"git status --short && rg -n 'completion\\.open_categories|favorite_paths|open_categories:' qutebrowser doc tests",workdir:"/app",max_output_tokens:5000})
]); r.forEach((x,i)=>text({i,...x}));

const r = await Promise.allSettled([
  tools.exec_command({cmd:"find .. -name AGENTS.md -print",workdir:"/app",max_output_tokens:2000}),
  tools.exec_command({cmd:"git status --short",workdir:"/app",max_output_tokens:2000}),
  tools.exec_command({cmd:"grep -R -n -E 'completion\\.open_categories|favorite_paths|open_categories:' qutebrowser doc tests 2>/dev/null | head -80",workdir:"/app",max_output_tokens:5000}),
  tools.exec_command({cmd:"find . -maxdepth 3 -iname '*help*' -o -name 'configdata.yml' | head -80",workdir:"/app",max_output_tokens:3000})
]); r.forEach((x,i)=>text({i,...x}));

const r = await Promise.allSettled([
  tools.exec_command({cmd:"sed -n '1080,1205p' qutebrowser/config/configdata.yml",workdir:"/app",max_output_tokens:5000}),
  tools.exec_command({cmd:"sed -n '1700,1845p' doc/help/settings.asciidoc",workdir:"/app",max_output_tokens:5000}),
  tools.exec_command({cmd:"find scripts -maxdepth 2 -type f | head -80",workdir:"/app",max_output_tokens:4000}),
  tools.exec_command({cmd:"grep -R -n -E 'settings.asciidoc|configdata.yml' scripts tests/unit/config 2>/dev/null | head -100",workdir:"/app",max_output_tokens:5000})
]); r.forEach((x,i)=>text({i,...x}));

const r = await Promise.allSettled([
  tools.exec_command({cmd:"grep -n -A85 -B5 'def generate_settings' scripts/dev/src2asciidoc.py",workdir:"/app",max_output_tokens:6500}),
  tools.exec_command({cmd:"grep -n -A10 -B5 'List/String' doc/help/settings.asciidoc | head -100",workdir:"/app",max_output_tokens:5000}),
  tools.exec_command({cmd:"grep -n -A10 -B2 '^\\[\\[completion\\|^=== completion' doc/help/settings.asciidoc | tail -100",workdir:"/app",max_output_tokens:5000}),
  tools.exec_command({cmd:"ls -a | head -60",workdir:"/app",max_output_tokens:2000})
]); r.forEach((x,i)=>text({i,...x}));

const r = await Promise.allSettled([
  tools.exec_command({cmd:"git diff -- qutebrowser/config/configdata.yml doc/help/settings.asciidoc",workdir:"/app",max_output_tokens:6000}),
  tools.exec_command({cmd:"grep -n -A18 -B2 'completion.favorite_paths' doc/help/settings.asciidoc",workdir:"/app",max_output_tokens:2500})
]); r.forEach((x,i)=>text({i,...x}));

const r = await Promise.allSettled([
  tools.exec_command({cmd:"pytest -q tests/unit/config/test_configdata.py",workdir:"/app",yield_time_ms:30000,max_output_tokens:3500}),
  tools.exec_command({cmd:"python -c 'from scripts.dev import src2asciidoc; src2asciidoc.generate_settings(\"doc/help/settings.asciidoc\")' && git diff --check -- qutebrowser/config/configdata.yml doc/help/settings.asciidoc",workdir:"/app",yield_time_ms:10000,max_output_tokens:1500})
]); r.forEach((x,i)=>text({i,...x}));
